  night: [
    { x: "بدء السريان: التاريخ المنصوص أو المتفق عليه (1/24)، وإلا فحين يثبت ارتضاء جميع المتفاوضين (2/24)، والمتأخر من تاريخ التزامه (3/24)، والأحكام الإجرائية من تاريخ تبني النص (4/24)؛ والسريان المؤقت في المادة (25).", pg: "224–225" },
    { x: "Pacta sunt servanda = «العقد شريعة المتعاقدين» = «المتعاقد عند تعاقده»؛ المادة (26): «كل معاهدة نافذة ملزمة لأطرافها، ويجب عليهم تنفيذها بحسن نية»؛ ويستوعب عند المؤلف القواعد العرفية الأخرى.", pg: "225–226" },
    { x: "نتائج الوفاء بالعهد أربع: إلزام السلطات والأجهزة، وعدم التذرع بالقانون الداخلي (المادة 27)، والاستمرار رغم تغير النظام أو الحكومة، والتنفيذ بحسن نية.", pg: "227–228" },
    { x: "عدم الرجعية (المادة 28) قاعدة، والأثر الرجعي استثناء بإرادة الأطراف (نص أو اتفاق مكتوب أو شفوي)؛ ومارفوماتيس (المحكمة الدائمة للعدل الدولي، 30 أغسطس 1924): الأثر الرجعي من طبيعة الموضوع.", pg: "229–230" },
    { x: "المكاني (المادة 29): كامل الإقليم البري والبحري والجوي إلا بإرادة الأطراف؛ الشرط الاستعماري (المستعمرات) والشرط الفيدرالي (الولايات أو الإمارات أو المقاطعات).", pg: "230–231" },
    { x: "المعاهدات المتتالية (المادة 30): علو الميثاق (103؛ 1/30 في اتفاقية 1969 و6/30 في اتفاقية 1986)، ثم المعاهدة المحال إليها (2/30)، ثم اللاحقة بين الأطراف أنفسهم (3/30)، والتي تجمع الطرفين عند اختلاف الأطراف (4/30).", pg: "232" },
    { x: "الضمانة الأساسية المسؤولية الدولية، وخمس أخرى: الاحتلال العسكري (فرساي 1919: الراين 15 عامًا)، والامتياز المالي (فرساي؛ والجزائر 1981)، وتعهد الدول الكبرى (1839 لمعاهدة لندن 1831)، والجهاز الدائم، والرقابة في المنظمات.", pg: "232–237" },
    { x: "نسبية الآثار (المادة 34) مبدأ عرفي مستقر؛ والاستثناء أساسه في غالب الأحيان موافقة الغير الصريحة أو الضمنية، وبعضه مراكز موضوعية تفرض تلقائيًا.", pg: "238–239" },
    { x: "الالتزام على الغير (35): إرادة الأطراف وموافقة صريحة مكتوبة، ولا يلغى إلا باتفاق الجانبين (1/37)؛ والحق (36): إرادة الأطراف وموافقة تفترض في اتفاقية 1969، وتخضع لقواعد المنظمة في اتفاقية 1986.", pg: "240–242" },
    { x: "شرط الدولة الأولى بالرعاية: مانح ومستفيد وغير مفضل، واتفاقية الأساس؛ استثناء عند الرأي الغالب والمؤلف حاليًا، وليس استثناءً عند رأي آخر وعند لجنة القانون الدولي على ما يبدو.", pg: "243–245" },
    { x: "دون موافقة الغير ثلاث: مراكز موضوعية (سويسرا 1815 بثماني دول، والقطب الجنوبي 1959 باثنتي عشرة دولة، والحدود)، وطرق مواصلات (القسطنطينية 1888 بتسع دول)، وكيانات جديدة (بلجيكا 1831، وهولندا 1839، ودانتزج 1919).", pg: "245–247" },
    { x: "المادة 6/2 من الميثاق ليست استثناءً على النسبية عند المؤلف (خلافًا للرأي الغالب)؛ ورأي محكمة العدل الدولية (11 أبريل 1949): شخصية الأمم المتحدة موضوعية، لأن خمسين دولة تستطيع خلق هذا الكيان.", pg: "248" },
    { x: "التفسير عملية ذهنية كاشفة؛ يختص به دوليًا الأطراف أولًا، وداخليًا القضاء أو وزارة الخارجية، ويفضل المؤلف السلطة المختصة بإدارة العلاقات الدولية.", pg: "249–251" },
    { x: "المناهج الرئيسية ثلاثة: النصي والشخصي والوظيفي، والعلاقة بينها تكاملية؛ والوسائل التكميلية في المادة (32)، ومنها الأعمال التحضيرية والظروف؛ والمكملة في إملاء الدكتور أربعة: الأعمال التفسيرية، والظروف الملابسة، ومفهوم المخالفة، والقياس.", pg: "252–256" }
  ],
